"""Separate actual held-boundary motion/capping from free-object instability."""
import argparse,csv,json,xml.etree.ElementTree as ET
from pathlib import Path
import numpy as np
from analyse import BASE,sha
from winch_transfer_assess import unique_row

def main():
 p=argparse.ArgumentParser();p.add_argument('--case',required=True);p.add_argument('--tag',required=True);a=p.parse_args();src=BASE/'results'/a.case;summary=json.loads((src/'summary.json').read_text());assert summary['status']=='RUN_COMPLETED_NOT_QUALIFIED';root=ET.parse(src/'scene.scn').getroot();dt=float(root.get('dt'));records=[];paths=[src/'summary.json',src/'scene.scn'];read=lambda f:list(csv.DictReader(f.open()))
 for i in range(3):
  for j in range(2):
   name=f'drive_{i}_{j}';drive=root.find(f"Node[@name='{name}']");ports=drive.find("Node[@name='ports']");q0=np.fromstring(ports.find('MechanicalObject').get('position'),sep=' ').reshape(-1,3);pull=np.fromstring(ports.find('CableConstraint').get('pullPoint'),sep=' ');L0=np.linalg.norm(q0[0]-pull);controller=next(c for c in root.findall('NativeCableSequence') if c.get('body')==f'@{name}/ports/points');stroke=float(controller.get('stroke'));f=src/f'{name}_phases.csv';paths.append(f);rows=[r for r in read(f) if r['phase']=='accepted_end'];mask=np.array([1.6-1e-12<=float(r['time_s'])<=2.+1e-12 for r in rows]);assert mask.sum()>=160;q=np.array([np.fromstring(r['q'],sep=' ').reshape(-1,3) for r in rows]);v=np.array([np.fromstring(r['v'],sep=' ').reshape(-1,3) for r in rows]);T=np.array([np.fromstring(r['lambda_Ns'],sep=' ')[unique_row(r['J'],0)]/dt for r in rows]);outT=np.array([np.fromstring(r['lambda_Ns'],sep=' ')[unique_row(r['J'],1)]/dt for r in rows]);error=L0-np.linalg.norm(q[:,0]-pull,axis=1)-stroke;records.append(dict(finger=i,tendon=j,hold_samples=int(mask.sum()),input_force_range_N=[float(T[mask].min()),float(T[mask].max())],output_force_range_N=[float(outT[mask].min()),float(outT[mask].max())],input_cap_samples=int((T[mask]>=1.5-1e-12).sum()),maximum_input_stroke_error_um=float(abs(error[mask]).max()*1e6),maximum_input_port_speed_mm_s=float(np.linalg.norm(v[mask,0],axis=1).max()*1000),maximum_output_port_speed_mm_s=float(np.linalg.norm(v[mask,1],axis=1).max()*1000)))
 obj=read(src/'object.csv');mask=np.array([1.6-1e-12<=float(r['time_s'])<=2.+1e-12 for r in obj]);velocity=np.array([np.fromstring(r['rigid_v'],sep=' ') for r in obj]);components=np.max(abs(velocity[mask,:3]),axis=0)*1000;still=max(r['maximum_output_port_speed_mm_s'] for r in records)<=1e-6 and all(r['input_cap_samples']==0 for r in records);d=dict(status='PASS_HELD_DRIVE_BOUNDARY_ISOLATION_ONLY' if still else 'ACTUAL_HELD_BOUNDARY_MOVES_OR_CAPS',case=a.case,records=records,object_hold_componentwise_maximum_absolute_speed_mm_s=components.tolist(),hypothesis_assessment='Input cap/backdrive is NOT an observed late excitation: both boundary ports essentially stationary; investigate Skin/contact/FEM motion rather than increase force or add winch brake' if still else 'Actual boundary motion/capping remains a possible coupling; correlation alone is not causation',source_sha256=sha(Path(__file__)),input_hashes={str(f.relative_to(BASE)):sha(f) for f in paths},scope='Read-only actual1.6–2s port q/v, exact Cable J row multipliers and original command. Stationary boundary excludes direct kinematic late excitation, not stored elastic energy or prior closing history. No wholeenergy/contactnormal/causal attribution, no numerical/physical PASS.');out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);(out/'producer.py').write_bytes(Path(__file__).read_bytes());(out/'summary.json').write_text(json.dumps(d,indent=2));print(json.dumps({k:v for k,v in d.items() if k!='input_hashes'},indent=2))
